-- --------------------------------------------------------

DROP TABLE IF EXISTS `orders`;

CREATE TABLE `orders` (
    `order_id` INT AUTO_INCREMENT PRIMARY KEY,
    `user_id` INT NOT NULL,
    `station_id` VARCHAR(50) NOT NULL,
    `start_time` DATETIME NOT NULL,
    `end_time` DATETIME NOT NULL,
    -- העמודות החדשות למדידת זמנים
    `charging_time` TIME DEFAULT '00:00:00',
    `extra_parking_time` TIME DEFAULT '00:00:00',
    `total_price` DECIMAL(10,2) NOT NULL,
    `status` ENUM('pending', 'rejected', 'approved', 'cancelled', 'charging', 'extra parking', 'completed') DEFAULT 'pending',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    -- הוספת אינדקסים לשיפור ביצועי שליפה
    KEY `idx_user_orders` (`user_id`),
    KEY `idx_station_orders` (`station_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--

