-- 1. הפעלת המתזמן (מוודא שהאירועים באמת ירוצו)
SET GLOBAL event_scheduler = ON;

-- 2. שינוי המפריד כדי שנוכל להשתמש בנקודה-פסיק בתוך הבלוק
DELIMITER //

-- 3. מחיקת האירוע אם הוא כבר קיים
DROP EVENT IF EXISTS auto_manage_order_statuses //

-- 4. יצירת האירוע מחדש עם הלוגיקה המשולבת
CREATE EVENT auto_manage_order_statuses
ON SCHEDULE EVERY 1 MINUTE
DO
BEGIN
    -- א. דחיית הזמנות ממתינות שזמן ההתחלה שלהן עבר
    UPDATE orders 
    SET status = 'rejected' 
    WHERE status = 'pending' AND start_time < NOW();

    -- ב. ביטול הזמנות מאושרות שעברה שעה מרגע יצירתן ולא מומשו
    UPDATE orders 
    SET status = 'cancelled' 
    WHERE status = 'approved' AND created_at < NOW() - INTERVAL 1 HOUR;
END //

-- 5. החזרת המפריד למצב הרגיל
DELIMITER ;

