-- עדכון טבלת העמדות (station) - מסנכרן את עמודת grade עם הממוצע החדש בטבלת rating
UPDATE station s 
SET grade = (
    SELECT ROUND(AVG(grade), 2) 
    FROM rating r 
    WHERE r.station_id = s.station_id
);
COMMIT;

-- --------------------------------------------------------
DROP TABLE IF EXISTS `opening_hours`;
CREATE TABLE IF NOT EXISTS `opening_hours` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `station_id` varchar(20) NOT NULL,
  `day_of_week` tinyint(1) NOT NULL COMMENT '1=Sunday, 7=Saturday',
  `open_time` time DEFAULT '00:00:00',
  `close_time` time DEFAULT '23:59:59',
  `is_closed` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `station_id` (`station_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

